local ActionDarkMainChallengeNode = Class('ActionDarkMainChallengeNode')
local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
local Cell1Path = "Game.UI.FightReady.ChaoticRecall.Cell.ActionDarkDreamMainLevelNewNormalCell"
local Cell2Path = "Game.UI.FightReady.ChaoticRecall.Cell.ActionDarkDreamMainLevelNewFinalCell"
local Cell1Name = "ActionDarkDreamMainLevelNewNormalCell"
local Cell2Name = "ActionDarkDreamMainLevelNewFinalCell"
local RankCount = 3

function ActionDarkMainChallengeNode:__init()

end

function ActionDarkMainChallengeNode:__delete()

end

function ActionDarkMainChallengeNode:Awake()
	self:AddUIClick()
	self:InitRankEvn()
end

function ActionDarkMainChallengeNode:InitRankEvn()
	self.rankEnv = {}
	for i = 1, RankCount do
		local node = self["InfoNode"..i]
		if node then
			local env = CfUtils.GetLuaScr(node,"Game.UI.FightReady.ChaoticRecall.Cell.ActionDarkDreamMainRankCell")
			if env then
				table.insert(self.rankEnv,env)
			end
		end
	end
end

function ActionDarkMainChallengeNode:OnFocus(focus)
	if focus then
		self:RefreshBtnRankState()
	end
end

function ActionDarkMainChallengeNode:AddUIClick()
	CfUtils.IsDuoLeInVisiable(self.BtnRank)
	SetButtonAction(self.BtnCheck,Bind(self,self.OnBtnRankClick))
	SetButtonAction(self.BtnRank,Bind(self,self.OnBtnRankClick))
	SetButtonAction(self.BtnStore,Bind(self,self.OnBtnStoreClick))
end

function ActionDarkMainChallengeNode:OnBtnRankClick()
	CfUtils.DialogOpen(Constants.UITypeIds.ActionDarkDreamNewFunctionRankDialog,{ groupId = self.groupId, index = self.index})
end

function ActionDarkMainChallengeNode:OnBtnStoreClick()
	---@type GroceryUtils
	local GroceryUtils = import('Game.Grocery.GroceryUtils')
	---@type GroceryConstants
	local GroceryConstants = import('Game.Grocery.GroceryConstants')
	GroceryUtils.OpenGroceryStore(GroceryConstants.GroceryType.NightMareQuest, {
		UIArgs(Constants.UITypeIds.ActionDarkDreamMainDialog)
	})
end

function ActionDarkMainChallengeNode:Refresh(groupId, dojo, index)
	self.groupId = groupId
	self.dojo = dojo
	self.index = index
	self:RefreshActionBtnRecommend()
	local nodeData = dojo:GetChallengeNodeData(index)
	self.nodeData = nodeData
	self:RefreshLoopListView()
	self:RefreshRankInfo()
	self:RefreshBtnRankState()
	local data = dojo:GetUpStarGroupData(index)
	UICommonUtils.RefreshCommonUpGroup(self.CommRoleBonusLayoutGroup, data, true,{{id = Constants.UITypeIds.ActionDarkDreamMainDialog}})
end

function ActionDarkMainChallengeNode:RefreshLoopListView()
	local count = table.count(self.nodeData)
	if not self.LevelRootScrollView.IsListViewInit then
		self.LevelRootScrollView:InitListView(count, Bind(self, self.OnGetItemByIndex))
	else
		GameUtils.ReloadData(self.LevelRootScrollView,count)
	end
end

function ActionDarkMainChallengeNode:RefreshRankInfo()
	local rankInfo = self.dojo:GetRankInfo(self.index)
	local isHave = table.count(rankInfo) > 0
	CfUtils.SetActive(self.Empty.gameObject,not isHave)
	CfUtils.SetActive(self.Content.gameObject, isHave)
	if isHave then
		for i, v in ipairs(self.rankEnv) do
			if rankInfo[i] then
				v:RefreshShow(rankInfo[i])
			else
				v:RefreshShow(nil)
			end
		end
	end
	CfUtils.IsDuoLeInVisiable(self.Empty.transform.parent)
end

function ActionDarkMainChallengeNode:OnGetItemByIndex(listView, index)
	if index < 0 or index >= #self.nodeData then
		return
	end
	local index = index + 1
	local cell = (index == table.count(self.nodeData)) and listView:NewListViewItem(Cell2Name) or listView:NewListViewItem(Cell1Name)
	local CellPath = (index == table.count(self.nodeData)) and Cell2Path or Cell1Path
	if not isNull(cell) then
		local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
		if not isNull(tableCellEnv) then
			tableCellEnv:RefreshShow(self.nodeData[index], self.groupId,self.index)
			tableCellEnv:SetCallBack(Bind(self,self.OnNodeClick))
		end
	end
	cell.transform:SetSiblingIndex(index - 1)
	return cell
end

function ActionDarkMainChallengeNode:RefreshBtnRankState()
	local isGet = self:IsGetRankReward()
	local redGo = GameUtils.GetRedPointGo(self.BtnRank)
	if isNotNull(redGo) then
		CfUtils.SetActive(redGo, not isGet)
	end
end

function ActionDarkMainChallengeNode:IsGetRankReward()
	local isGet = self.dojo:IsGetRankReward(self.index)
	return isGet
end

function ActionDarkMainChallengeNode:OnNodeClick()

end

function ActionDarkMainChallengeNode:RefreshActionBtnRecommend()
	---@type ChaoticRecallTagVo
	local vo       = ChaoticRecallUtils.GetChaoticRecallTagVo(self.groupId)
	local tipBoard = vo.tipBoard
	local isShow   = tipBoard > 0
	GameUtils.UpdateUIShowState(self.ActionBtnRecommend.gameObject, isShow)
	if isShow then
		UICommonUtils.SetActionRecommendTipsId(self.ActionBtnRecommend, tipBoard)
	end
end

function ActionDarkMainChallengeNode:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return ActionDarkMainChallengeNode